import { createI18n } from 'vue-i18n';
import MESSAGES from './messages';

/**
 * Client Portal i18n — SaaS adaptation of the stocky reference.
 *
 * stocky fetches resources/lang/{locale}/portal.php through
 * GET /api/portal/translations/{locale} and persists the choice with
 * POST /api/portal/locale. Neither exists on this backend (and the backend /
 * routes are off-limits), so the same message files are BUNDLED
 * (src/portal/messages.js, generated by resources/scripts/gen-portal-messages.cjs) and
 * the choice is remembered per browser in localStorage.
 *
 * Starting locale: window.__PORTAL_LOCALE__ when portal.blade.php injects the
 * app locale, else the stored choice, else 'en'. The supported set comes from
 * window.__PORTAL_LOCALES__ when injected, else the four bundled locales.
 */

const FALLBACK_LOCALES = { en: 'English', fr: 'Français', es: 'Español', ar: 'العربية' };

export const SUPPORTED_LOCALES =
  window.__PORTAL_LOCALES__ && typeof window.__PORTAL_LOCALES__ === 'object' && Object.keys(window.__PORTAL_LOCALES__).length
    ? Object.fromEntries(Object.entries(window.__PORTAL_LOCALES__).filter(([code]) => code in MESSAGES))
    : FALLBACK_LOCALES;

const RTL_LOCALES = ['ar'];
const STORAGE_KEY = 'portal_language';

export function isRtlLocale(locale) {
  return RTL_LOCALES.includes(locale);
}

export function isSupported(locale) {
  return !!locale && Object.prototype.hasOwnProperty.call(SUPPORTED_LOCALES, locale);
}

export function initialLocale() {
  try {
    const stored = window.localStorage.getItem(STORAGE_KEY);
    if (isSupported(stored)) return stored;
  } catch (e) { /* storage unavailable */ }
  const fromServer = window.__PORTAL_LOCALE__;
  if (isSupported(fromServer)) return fromServer;
  return 'en';
}

export const i18n = createI18n({
  legacy: false,          // Composition API mode
  globalInjection: true,  // $t() in templates / this.$t in Options API
  locale: initialLocale(),
  fallbackLocale: 'en',
  messages: MESSAGES,
  missingWarn: false,
  fallbackWarn: false,
  silentTranslationWarn: true,
  silentFallbackWarn: true,
});

export function applyDirection(locale) {
  document.documentElement.setAttribute('dir', isRtlLocale(locale) ? 'rtl' : 'ltr');
  document.documentElement.setAttribute('lang', locale);
}

/**
 * Activates a bundled locale. Kept async so main.js / LanguageSwitcher keep
 * the reference's `await loadLocale()` shape. Never throws.
 */
export async function loadLocale(locale) {
  if (!isSupported(locale)) locale = 'en';
  i18n.global.locale.value = locale;
  applyDirection(locale);
  try {
    window.localStorage.setItem(STORAGE_KEY, locale);
  } catch (e) { /* ignore storage errors */ }
  return locale;
}

/** User-initiated switch (no server round-trip on this backend). */
export async function setLocale(locale) {
  if (!isSupported(locale)) return;
  await loadLocale(locale);
}

export function currentLocale() {
  return i18n.global.locale.value;
}

/**
 * Translate an enum-ish API value (status, type, job_type) through a prefixed
 * key, falling back to the raw value when no translation exists.
 *   enumLabel('status_', 'in_progress') -> $t('status_in_progress')
 */
export function enumLabel(prefix, value) {
  if (value === null || value === undefined || value === '') return '';
  const key = prefix + String(value).toLowerCase().trim().replace(/[\s-]+/g, '_');
  return i18n.global.te(key) ? i18n.global.t(key) : String(value);
}
